from __future__ import annotations

from typing import Any, Union

from pysnmp.proto import rfc1902

from taf.hw.pdu.device_status import DeviceStatus
from taf.hw.pdu.exceptions import BadPortNumber

from .snmp import SnmpPdu


class EPC(SnmpPdu):
    def __init__(
        self,
        host: str,
        timeout: Union[float, int] = 1,
        num_of_ports: int = 12,
        snmp_user: dict[str, Any] | None = None,
        community: str = "private",
    ) -> None:
        """
        :param string host: IP address or domain name of the EPC device.
        :param float timeout: Response timeout in seconds, default value is 1
        :param int num_of_ports: number of ports of pdu, default is 12
        :param dict snmp_user (required only for SNMPv3): User configuration for SNMPv3 with keys: userName, authKey,
                          privKey, authProtocol (SHA/MD5), privProtocol (AES/DES)
        :param community: Community string used by SNMPv1/2.
        """
        super().__init__(host, timeout, snmp_user, community)

        self.num_of_ports = int(num_of_ports)
        self._version = 1
        self._key = "1.3.6.1.4.1.28507.38.1.3.1.2.1.3"

    @property
    def _port_setting(self):
        return {DeviceStatus.OFF: "0", DeviceStatus.ON: "1"}

    def _get_oid_value(self, value):
        return rfc1902.Integer(self._port_setting[value])

    def _build_snmp_oid(self, port):
        self._verify_port(port)
        return f"{self._key}.{port}"

    def _verify_port(self, port):
        if port not in range(1, self.num_of_ports + 1):
            raise BadPortNumber(f"Port number is invalid: {port}")


class EPC8220_1(EPC):
    def __init__(self, host, timeout=1, num_of_ports=12, snmp_user=None, community="private"):
        super(EPC8220_1, self).__init__(
            host=host,
            timeout=timeout,
            num_of_ports=num_of_ports,
            snmp_user=snmp_user,
            community=community,
        )


